node --test tests/visible.test.mjs && node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createClient } from './src/client.mjs';
import { delayFor, shouldRetry } from './src/policy.mjs';

const sent = [];
const delays = [];
let keyCount = 0;
const statuses = [503, 429, 200];
const request = createClient({
  transport: async ({ headers }) => {
    sent.push(headers);
    const status = statuses.shift();
    return { status, headers: status === 503 ? { 'Retry-After': '2' } : {} };
  },
  sleep: async ms => delays.push(ms),
  keyFactory: () => `key-${++keyCount}`,
  maxAttempts: 3,
  baseMs: 20
});
assert.equal((await request({ method: 'POST', url: '/items', headers: { 'x-test': 'kept' } })).status, 200);
assert.equal(keyCount, 1);
assert.deepEqual(sent.map(headers => headers['idempotency-key']), ['key-1', 'key-1', 'key-1']);
assert.ok(sent.every(headers => headers['x-test'] === 'kept'));
assert.deepEqual(delays, [2000, 40]);
const explicit = createClient({
  transport: async ({ headers }) => { assert.equal(headers['Idempotency-Key'], 'caller-key'); return { status: 200 }; },
  sleep: async () => {}, keyFactory: () => { throw new Error('should not generate'); }
});
assert.equal((await explicit({ method: 'POST', url: '/', headers: { 'Idempotency-Key': 'caller-key' } })).status, 200);
assert.deepEqual([429, 500, 599, 600, 404].map(status => shouldRetry({ status })), [true, true, true, false, false]);
assert.equal(delayFor({ headers: { 'retry-after': '1.5' } }, 1, 100), 1500);
assert.equal(delayFor({ headers: { 'retry-after': 'not numeric' } }, 3, 100), 400);
console.log('additional contract assertions passed');
EOF

